// Models the engine carries inside its own binary. A ModelComponent::filename
// that starts with BuiltinModels::pathPrefix() names one of them instead of a
// file in the project directory, so a fresh scene, an exported build or a
// machine without the asset still renders the same geometry.
//
// The bytes are the committed headers generated by
// engine/generate_builtin_model.py, not a runtime file lookup.

#ifndef BUILTINMODEL_H
#define BUILTINMODEL_H

#include "Export.h"

#include <string>
#include <vector>

namespace quantum {

    class QUANTUM_API BuiltinModels {
    public:
        // "builtin://" - the scheme that keeps these paths out of the filesystem.
        static const char* pathPrefix();

        // The model new 3D entities are created with.
        static const char* defaultPath();

        static bool isBuiltinPath(const std::string& path);

        // GLB bytes for a builtin path, or null when the name is unknown.
        // The result stays valid for the process lifetime; the copy happens once.
        static const std::vector<unsigned char>* find(const std::string& path);
    };

}

#endif //BUILTINMODEL_H
